        'Dear @Oula.michel,    I hope you are doing well.    Please find the response for each point provided from your end:    ? The risk factors and parameters used in the scoring model    SELECT SP.PARAMETER_CODE PARAMETER_CODE, SP.PARAMETER_ELEMENT PARAMETER_ELEMENT, ST.BUSINESS_NAME TABLE_CODE_DESC, SCO.COLUMN_BUSINESS_NAME COLUMN_CODE_DESC, DECODE (SP.SEGMENT_BASED_FLAG,''0'',''No'',''1'',''Yes'') SEGMENT_BASED_FLAG_DESC ,DECODE(SP.ACTIVE_FLAG,''0'',''Inactive'',''1'',''Active'') as ACTIVE_FLAG_DESC, DECODE(SP.MULTI_SINGLE_FLAG,0,''Single Value'',1,''Monthly Values'') as MULTI_SINGLE_FLAG_DESC ,PARAMETER_ELEMENT_NAT,DECODE (SP.INDV_CORR_FLAG,''1'',''Individual'',''2'',''Entity'',''0'',''Both'') INDV_CORR_FLAG_DESC, INDV_CORR_FLAG ,SP.GROUP_CODE as GROUP_CODE,G.DESC_ENG as GROUP_CODE_DESC,SP.ONLINE_FLAG ,Para.DES_ENG as PARAMETER_CATEGORY_CODE_DESC FROM PIO_RISK_ASSESSMENT_PARAMETERS SP Left Join PIO_RISK_ASSESSMENT_TABLES ST ON (SP.TABLE_Code = ST.TABLE_CODE) Left Join PIO_RISK_ASSESSMENT_COLUMNS SCO ON (SP.COLUMN_CODE = SCO.COLUMN_CODE and SP.TABLE_Code = SCO.TABLE_CODE) left join PIO_RISK_ASSESSMENT_GROUP G on(Sp.GROUP_CODE=G.GROUP_CODE AND G.COUNTRY_CODE=275 AND G.INST_CODE=1) LEFT JOIN PIO_RISK_PARAMETER_CATEGORY Para ON ( Sp.PARAMETER_CATEGORY_CODE = Para.PARAMETER_CATEGORY_CODE AND Para.COUNTRY_CODE = 275 AND Para.INST_CODE = 1) where SP.COUNTRY_CODE =275 AND SP.INST_CODE = 1 ORDER BY TO_NUMBER(SP.Parameter_Code)    ? Assigned weightings and scoring logic (where applicable)      select RW.*,RPara.PARAMETER_ELEMENT as PARAMETER_CODE_DES from PIO_RISK_ASSESSMENT_PARAMETERS RPara    left JOIN PIO_RISK_PARAMETER_WEIGHT RW on(RPara.PARAMETER_CODE = RW.PARAMETER_CODE   AND RPara.INDV_CORR_FLAG = RW.INDV_CORP_IND and RPara.PARAMETER_CATEGORY_CODE = RW.PARAMETER_CATEGORY_CODE   AND RPara.ONLINE_FLAG = RW.ONLINE_FLAG   AND RW.country_code =RPara.country_code   AND RW.inst_code =RPara.inst_code ) where RPara.PARAMETER_CODE <> 0 AND RPara.COUNTRY_CODE = 275 AND RPara.INST_CODE = 1 AND RPara.ONLINE_FLAG=1 AND RPara.INDV_CORR_FLAG=1 AND RPara.ACTIVE_FLAG = 1 order by RW.PARAMETER_CODE     ? Any thresholds or rules applied for risk categorization  not applicable     ? The date of the most recent configuration or any changes made    Audit report from admi panel interface',
